/************************************內部建置************************************************/
DELETE FROM DS_SEC.CF_TXN_CURRENCY WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_TXN_MAEC WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_TXN_STYPE WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_TXN_FPBR WHERE YYYYMM = :ym;

CREATE TABLE TRANS_INIT
AS
SELECT PARTY_ID_MASK AS PARTY_ID
,TXN_YYYYMM
,PROD_TYPE_CODE
,PROD_MTYPE_CODE
,PROD_STYPE_CODE
,CURRENCY_CODE
,BUY_SELL_CODE
,CHANNEL_CODE
,TXN_TYPE_CODE
,SUM(TXN_AMT_TWD)TXN_AMT_TWD
,COUNT(*) TRANS_NUM
FROM(
/*****************************************************/
--商品交易
--台股海外股
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_TYPE_CODE,CHANNEL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_STOCK_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --不限用途
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE, TXN_TYPE_CODE,CHANNEL_CODE
,'' as CURRENCY_CODE,'' as BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_LOAN_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --借券
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,CHANNEL_CODE
,'' as CURRENCY_CODE,BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_BSBL_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --期權
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,CHANNEL_CODE
,CURRENCY_CODE,BUY_SELL_CODE,UNIT_PRICE*TXN_UNIT_QTY*EXCHG_RATE TXN_AMT_TWD from DM_S_VIEW.M_AT_FUTURE_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --海外債
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,CHANNEL_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_BOND_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --基金
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,CHANNEL_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_FUND_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --結構型
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,CHANNEL_CODE
,CURRENCY_CODE,BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_SN_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
union all --壽險
select PARTY_ID,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,TXN_TYPE_CODE,
'' AS CHANNEL_CODE, CURRENCY_CODE,'' as BUY_SELL_CODE,TXN_AMT_TWD from DM_S_VIEW.M_AT_INSURANCE_TXN
where TXN_YYYYMM between TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym AND POLICY_STATUS_CODE IN ('0', '1')
) A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
group by PARTY_ID_MASK,TXN_YYYYMM,PROD_TYPE_CODE,PROD_MTYPE_CODE,PROD_STYPE_CODE,
CURRENCY_CODE,BUY_SELL_CODE, CHANNEL_CODE, TXN_TYPE_CODE;

/************************************對外輸出************************************************/
INSERT INTO DS_SEC.CF_TXN_STYPE
SELECT A.customer_id
    ,A.YYYYMM
    --  一般股票
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_BUY_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_BUY_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_BUY_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_BUY_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_SELL_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_SELL_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_SELL_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_SELL_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='011' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='011' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STGS_TXN_AMT_12M
    
    --  股票型ETF
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_BUY_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_BUY_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_BUY_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_BUY_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_SELL_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_SELL_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_SELL_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_SELL_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='019' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='019' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STETF_TXN_AMT_12M
    
    --  認股權證
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_BUY_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_BUY_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_BUY_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_BUY_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_SELL_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_SELL_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_SELL_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_SELL_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='012' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='012' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS STWA_TXN_AMT_12M
    
    --  其他類股票
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_BUY_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_BUY_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_BUY_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_BUY_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_SELL_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_SELL_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_SELL_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_SELL_AMT_12M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OST_TXN_AMT_12M
    -- IPO 基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('028', '029') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDIPO_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('028', '029') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDIPO_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('028', '029') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDIPO_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('028', '029') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDIPO_TXN_AMT_12M
    
    -- 債券型基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('022', '027') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDB_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('022', '027') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDB_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('022', '027') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDB_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('022', '027') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDB_TXN_AMT_12M
    
    -- 平衡型及多重資產基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='023' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDBA_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='023' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDBA_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='023' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDBA_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='023' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDBA_TXN_AMT_12M
    
    -- 股票型基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='021' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDST_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='021' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDST_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='021' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDST_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='021' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDST_TXN_AMT_12M
    
    -- 貨幣型基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='024' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDCU_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='024' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDCU_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='024' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDCU_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='024' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FDCU_TXN_AMT_12M
    
    -- 其他型基金
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('025', '026') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFD_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('025', '026') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFD_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('025', '026') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFD_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('025', '026') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFD_TXN_AMT_12M
    
    -- 公司債
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE IN ('032') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBC_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('032') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBC_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('032') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBC_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE IN ('032') THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBC_TXN_AMT_12M
    
    -- 公債
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE ='031' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBG_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='031' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBG_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='031' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBG_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE ='031' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBG_TXN_AMT_12M
    
     -- 金融債
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='033' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBF_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='033' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBF_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='033' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBF_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='033' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FBF_TXN_AMT_12M
    
     -- 其他類海外債
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='034' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFB_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='034' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFB_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='034' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFB_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='034' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OFB_TXN_AMT_12M
    
    -- 境內型結構商品
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE ='540' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS NSN_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='540' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS NSN_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='540' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS NSN_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='540' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS NSN_TXN_AMT_12M
    
    -- 境外型結構商品
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE ='240' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FSN_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='240' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FSN_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='240' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FSN_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE ='240' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS FSN_TXN_AMT_12M
    
    -- 儲蓄型保單
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='0L1' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INWL_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L1' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INWL_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L1' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INWL_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L1' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INWL_TXN_AMT_12M

    -- 保障型保單
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='0L2' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INPO_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L2' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INPO_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L2' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INPO_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L2' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INPO_TXN_AMT_12M

    -- 投資型保單
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='0L3' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INUL_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L3' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INUL_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L3' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INUL_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L3' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS INUL_TXN_AMT_12M

    -- 其他型保單
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_STYPE_CODE='0L4' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OIN_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L4' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OIN_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L4' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OIN_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_STYPE_CODE='0L4' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OIN_TXN_AMT_12M
    
     --  國內期貨
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='3C0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFC_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3C0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFC_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3C0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFC_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3C0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFC_TXN_AMT_12M
    
    -- 國外期貨
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='3F0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFF_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3F0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFF_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3F0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFF_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3F0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS UFF_TXN_AMT_12M
    
    -- 3. OPTION 選擇權
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='3P0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OP_TXN_AMT_M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3P0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OP_TXN_AMT_3M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3P0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OP_TXN_AMT_6M
    ,ROUND(SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='3P0' THEN B.TXN_AMT_TWD ELSE 0 END),0) AS OP_TXN_AMT_12M
FROM DS_SEC.CF_CUSTID A
LEFT JOIN TRANS_INIT B
ON A.CUSTOMER_ID = B.PARTY_ID
WHERE A.YYYYMM = :ym
GROUP BY A.CUSTOMER_ID,A.YYYYMM;
INSERT INTO DS_SEC.CF_TXN_MAEC
SELECT A.CUSTOMER_ID
      ,A.YYYYMM
      -- 3. Foreign Stock 海外股票
      ,ROUND(FSMA_NUM_M, 0) AS FSMA_TXN_PROD_M
      ,ROUND(CASE WHEN (FSMA_NUM_M = NULL AND FSMA_NUM_L = NULL) THEN NULL ELSE FSMA_NUM_M - FSMA_NUM_L END, 0) AS FSMA_TXN_PROD_M_MDIFF
      ,ROUND(CASE WHEN FSMA_NUM_L != 0 THEN (FSMA_NUM_M / FSMA_NUM_L)-1 ELSE NULL END, 4) AS FSMA_TXN_PROD_M_RDIFF
      ,ROUND(FSMA_AMT_M, 0) AS FSMA_TXN_AMT_M
      ,ROUND(CASE WHEN (FSMA_AMT_M = 0 AND FSMA_AMT_L = 0) THEN NULL ELSE FSMA_AMT_M - FSMA_AMT_L END, 0) AS FSMA_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN FSMA_AMT_L != 0 THEN (FSMA_AMT_M / FSMA_AMT_L)-1 ELSE NULL END, 4) AS FSMA_TXN_AMT_M_RDIFF
      ,ROUND(FSMA_NUM_3M, 0) AS FSMA_TXN_PROD_3M
      ,ROUND(CASE WHEN (FSMA_NUM_3M = NULL AND FSMA_NUM_3ML = NULL) THEN NULL ELSE FSMA_NUM_3M - FSMA_NUM_3ML END, 0) AS FSMA_TXN_PROD_3M_MDIFF
      ,ROUND(CASE WHEN FSMA_NUM_3ML != 0 THEN (FSMA_NUM_3M / FSMA_NUM_3ML)-1 ELSE NULL END, 4) AS FSMA_TXN_PROD_3M_RDIFF
      ,ROUND(FSMA_AMT_3M, 0) AS FSMA_TXN_AMT_3M
      ,ROUND(CASE WHEN (FSMA_AMT_3M = 0 AND FSMA_AMT_3ML = 0) THEN NULL ELSE FSMA_AMT_3M - FSMA_AMT_3ML END, 0) AS FSMA_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN FSMA_AMT_3ML != 0 THEN (FSMA_AMT_3M / FSMA_AMT_3ML)-1 ELSE NULL END, 4) AS FSMA_TXN_AMT_3M_RDIFF
      ,ROUND(FSMA_NUM_6M, 0) AS FSMA_TXN_PROD_6M
      ,ROUND(CASE WHEN (FSMA_NUM_6M = NULL AND FSMA_NUM_6ML = NULL) THEN NULL ELSE FSMA_NUM_6M - FSMA_NUM_6ML END, 0) AS FSMA_TXN_PROD_6M_MDIFF
      ,ROUND(CASE WHEN FSMA_NUM_6ML != 0 THEN (FSMA_NUM_6M / FSMA_NUM_6ML)-1 ELSE NULL END, 4) AS FSMA_TXN_PROD_6M_RDIFF
      ,ROUND(FSMA_AMT_6M, 0) AS FSMA_TXN_AMT_6M
      ,ROUND(CASE WHEN (FSMA_AMT_6M = 0 AND FSMA_AMT_6ML = 0) THEN NULL ELSE FSMA_AMT_6M - FSMA_AMT_6ML END, 0) AS FSMA_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN FSMA_AMT_6ML != 0 THEN (FSMA_AMT_6M / FSMA_AMT_6ML)-1 ELSE NULL END, 4) AS FSMA_TXN_AMT_6M_RDIFF
      ,ROUND(FSMA_NUM_12M, 0) AS FSMA_TXN_PROD_12M
      ,ROUND(CASE WHEN (FSMA_NUM_12M = 0 AND FSMA_NUM_12ML = 0) THEN NULL ELSE FSMA_NUM_12M - FSMA_NUM_12ML END, 0) AS FSMA_TXN_PROD_12M_MDIFF
      ,ROUND(CASE WHEN FSMA_NUM_12ML != 0 THEN (FSMA_NUM_12M / FSMA_NUM_12ML)-1 ELSE NULL END, 4) AS FSMA_TXN_PROD_12M_RDIFF
      ,ROUND(FSMA_AMT_12M, 0) AS FSMA_TXN_AMT_12M
      ,ROUND(CASE WHEN (FSMA_AMT_12M = 0 AND FSMA_AMT_12ML = 0) THEN NULL ELSE FSMA_AMT_12M - FSMA_AMT_12ML END, 0) AS FSMA_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN FSMA_AMT_12ML != 0 THEN (FSMA_AMT_12M / FSMA_AMT_12ML)-1 ELSE NULL END, 4) AS FSMA_TXN_AMT_12M_RDIFF
      ,ROUND(FSEC_NUM_M, 0) AS FSEC_TXN_PROD_M
      ,ROUND(CASE WHEN (FSEC_NUM_M = 0 AND FSEC_NUM_L = 0) THEN NULL ELSE FSEC_NUM_M - FSEC_NUM_L END, 0) AS FSEC_TXN_PROD_M_MDIFF
      ,ROUND(CASE WHEN FSEC_NUM_L != 0 THEN (FSEC_NUM_M / FSEC_NUM_L)-1 ELSE NULL END, 4) AS FSEC_TXN_PROD_M_RDIFF
      ,ROUND(FSEC_AMT_M, 0) AS FSEC_TXN_AMT_M
      ,ROUND(CASE WHEN (FSEC_AMT_M = 0 AND FSEC_AMT_L = 0) THEN NULL ELSE FSEC_AMT_M - FSEC_AMT_L END, 0) AS FSEC_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN FSEC_AMT_L != 0 THEN (FSEC_AMT_M / FSEC_AMT_L)-1 ELSE NULL END, 4) AS FSEC_TXN_AMT_M_RDIFF
      ,ROUND(FSEC_NUM_3M, 0) AS FSEC_TXN_PROD_3M
      ,ROUND(CASE WHEN (FSEC_NUM_3M = 0 AND FSEC_NUM_3ML = 0) THEN NULL ELSE FSEC_NUM_3M - FSEC_NUM_3ML END, 0) AS FSEC_TXN_PROD_3M_MDIFF
      ,ROUND(CASE WHEN FSEC_NUM_3ML != 0 THEN (FSEC_NUM_3M / FSEC_NUM_3ML)-1 ELSE NULL END, 4) AS FSEC_TXN_PROD_3M_RDIFF
      ,ROUND(FSEC_AMT_3M, 0) AS FSEC_TXN_AMT_3M
      ,ROUND(CASE WHEN (FSEC_AMT_3M = 0 AND FSEC_AMT_3ML = 0) THEN NULL ELSE FSEC_AMT_3M - FSEC_AMT_3ML END, 0) AS FSEC_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN FSEC_AMT_3ML != 0 THEN (FSEC_AMT_3M / FSEC_AMT_3ML)-1 ELSE NULL END, 4) AS FSEC_TXN_AMT_3M_RDIFF
      ,ROUND(FSEC_NUM_6M, 0) AS FSEC_TXN_PROD_6M
      ,ROUND(CASE WHEN (FSEC_NUM_6M = 0 AND FSEC_NUM_6ML = 0) THEN NULL ELSE FSEC_NUM_6M - FSEC_NUM_6ML END, 0) AS FSEC_TXN_PROD_6M_MDIFF
      ,ROUND(CASE WHEN FSEC_NUM_6ML != 0 THEN (FSEC_NUM_6M / FSEC_NUM_6ML)-1 ELSE NULL END, 4) AS FSEC_TXN_PROD_6M_RDIFF
      ,ROUND(FSEC_AMT_6M, 0) AS FSEC_TXN_AMT_6M
      ,ROUND(CASE WHEN (FSEC_AMT_6M = 0 AND FSEC_AMT_6ML = 0) THEN NULL ELSE FSEC_AMT_6M - FSEC_AMT_6ML END, 0) AS FSEC_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN FSEC_AMT_6ML != 0 THEN (FSEC_AMT_6M / FSEC_AMT_6ML)-1 ELSE NULL END, 4) AS FSEC_TXN_AMT_6M_RDIFF
      ,ROUND(FSEC_NUM_12M, 0) AS FSEC_TXN_PROD_12M
      ,ROUND(CASE WHEN (FSEC_NUM_12M = 0 AND FSEC_NUM_12ML = 0) THEN NULL ELSE FSEC_NUM_12M - FSEC_NUM_12ML END, 0) AS FSEC_TXN_PROD_12M_MDIFF
      ,ROUND(CASE WHEN FSEC_NUM_12ML != 0 THEN (FSEC_NUM_12M / FSEC_NUM_12ML)-1 ELSE NULL END, 4) AS FSEC_TXN_PROD_12M_RDIFF
      ,ROUND(FSEC_AMT_12M, 0) AS FSEC_TXN_AMT_12M
      ,ROUND(CASE WHEN (FSEC_AMT_12M = 0 AND FSEC_AMT_12ML = 0) THEN NULL ELSE FSEC_AMT_12M - FSEC_AMT_12ML END, 0) AS FSEC_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN FSEC_AMT_12ML != 0 THEN (FSEC_AMT_12M / FSEC_AMT_12ML)-1 ELSE NULL END, 4) AS FSEC_TXN_AMT_12M_RDIFF
      
     -- 5. 台股 Stock
      ,ROUND(STMA_NUM_M, 0) AS STMA_TXN_PROD_M
      ,ROUND(CASE WHEN (STMA_NUM_M = 0 AND STMA_NUM_L = 0) THEN NULL ELSE STMA_NUM_M - STMA_NUM_L END, 0) AS STMA_TXN_PROD_M_MDIFF
      ,ROUND(CASE WHEN STMA_NUM_L != 0 THEN (STMA_NUM_M / STMA_NUM_L)-1 ELSE NULL END, 4) AS STMA_TXN_PROD_M_RDIFF
      ,ROUND(STMA_AMT_M, 0) AS STMA_TXN_AMT_M
      ,ROUND(CASE WHEN (STMA_AMT_M = 0 AND STMA_AMT_L = 0) THEN NULL ELSE STMA_AMT_M - STMA_AMT_L END, 0) AS STMA_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN STMA_AMT_L != 0 THEN (STMA_AMT_M / STMA_AMT_L)-1 ELSE NULL END, 4) AS STMA_TXN_AMT_M_RDIFF
      ,ROUND(STMA_NUM_3M, 0) AS STMA_TXN_PROD_3M
      ,ROUND(CASE WHEN (STMA_NUM_3M = 0 AND STMA_NUM_3ML = 0) THEN NULL ELSE STMA_NUM_3M - STMA_NUM_3ML END, 0) AS STMA_TXN_PROD_3M_MDIFF
      ,ROUND(CASE WHEN STMA_NUM_3ML != 0 THEN (STMA_NUM_3M / STMA_NUM_3ML)-1 ELSE NULL END, 4) AS STMA_TXN_PROD_3M_RDIFF
      ,ROUND(STMA_AMT_3M, 0) AS STMA_TXN_AMT_3M
      ,ROUND(CASE WHEN (STMA_AMT_3M = 0 AND STMA_AMT_3ML = 0) THEN NULL ELSE STMA_AMT_3M - STMA_AMT_3ML END, 0) AS STMA_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN STMA_AMT_3ML != 0 THEN (STMA_AMT_3M / STMA_AMT_3ML)-1 ELSE NULL END, 4) AS STMA_TXN_AMT_3M_RDIFF
      ,ROUND(STMA_NUM_6M, 0) AS STMA_TXN_PROD_6M
      ,ROUND(CASE WHEN (STMA_NUM_6M = 0 AND STMA_NUM_6ML = 0) THEN NULL ELSE STMA_NUM_6M - STMA_NUM_6ML END, 0) AS STMA_TXN_PROD_6M_MDIFF
      ,ROUND(CASE WHEN STMA_NUM_6ML != 0 THEN (STMA_NUM_6M / STMA_NUM_6ML)-1 ELSE NULL END, 4) AS STMA_TXN_PROD_6M_RDIFF
      ,ROUND(STMA_AMT_6M, 0) AS STMA_TXN_AMT_6M
      ,ROUND(CASE WHEN (STMA_AMT_6M = 0 AND STMA_AMT_6ML = 0) THEN NULL ELSE STMA_AMT_6M - STMA_AMT_6ML END, 0) AS STMA_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN STMA_AMT_6ML != 0 THEN (STMA_AMT_6M / STMA_AMT_6ML)-1 ELSE NULL END, 4) AS STMA_TXN_AMT_6M_RDIFF
      ,ROUND(STMA_NUM_12M, 0) AS STMA_TXN_PROD_12M
      ,ROUND(CASE WHEN (STMA_NUM_12M = 0 AND STMA_NUM_12ML = 0) THEN NULL ELSE STMA_NUM_12M - STMA_NUM_12ML END, 0) AS STMA_TXN_PROD_12M_MDIFF
      ,ROUND(CASE WHEN STMA_NUM_12ML != 0 THEN (STMA_NUM_12M / STMA_NUM_12ML)-1 ELSE NULL END, 4) AS STMA_TXN_PROD_12M_RDIFF
      ,ROUND(STMA_AMT_12M, 0) AS STMA_TXN_AMT_12M
      ,ROUND(CASE WHEN (STMA_AMT_12M = 0 AND STMA_AMT_12ML = 0) THEN NULL ELSE STMA_AMT_12M - STMA_AMT_12ML END, 0) AS STMA_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN STMA_AMT_12ML != 0 THEN (STMA_AMT_12M / STMA_AMT_12ML)-1 ELSE NULL END, 4) AS STMA_TXN_AMT_12M_RDIFF
      ,ROUND(STEC_NUM_M, 0) AS STEC_TXN_PROD_M
      ,ROUND(CASE WHEN (STEC_NUM_M = 0 AND STEC_NUM_L = 0) THEN NULL ELSE STEC_NUM_M - STEC_NUM_L END, 0) AS STEC_TXN_PROD_M_MDIFF
      ,ROUND(CASE WHEN STEC_NUM_L != 0 THEN (STEC_NUM_M / STEC_NUM_L)-1 ELSE NULL END, 4) AS STEC_TXN_PROD_M_RDIFF
      ,ROUND(STEC_AMT_M, 0) AS STEC_TXN_AMT_M
      ,ROUND(CASE WHEN (STEC_AMT_M = 0 AND STEC_AMT_L = 0) THEN NULL ELSE STEC_AMT_M - STEC_AMT_L END, 0) AS STEC_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN STEC_AMT_L != 0 THEN (STEC_AMT_M / STEC_AMT_L)-1 ELSE NULL END, 4) AS STEC_TXN_AMT_M_RDIFF
      ,ROUND(STEC_NUM_3M, 0) AS STEC_TXN_PROD_3M
      ,ROUND(CASE WHEN (STEC_NUM_3M = 0 AND STEC_NUM_3ML = 0) THEN NULL ELSE STEC_NUM_3M - STEC_NUM_3ML END, 0) AS STEC_TXN_PROD_3M_MDIFF
      ,ROUND(CASE WHEN STEC_NUM_3ML != 0 THEN (STEC_NUM_3M / STEC_NUM_3ML)-1 ELSE NULL END, 4) AS STEC_TXN_PROD_3M_RDIFF
      ,ROUND(STEC_AMT_3M, 0) AS STEC_TXN_AMT_3M
      ,ROUND(CASE WHEN (STEC_AMT_3M = 0 AND STEC_AMT_3ML = 0) THEN NULL ELSE STEC_AMT_3M - STEC_AMT_3ML END, 0) AS STEC_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN STEC_AMT_3ML != 0 THEN (STEC_AMT_3M / STEC_AMT_3ML)-1 ELSE NULL END, 4) AS STEC_TXN_AMT_3M_RDIFF
      ,ROUND(STEC_NUM_6M, 0) AS STEC_TXN_PROD_6M
      ,ROUND(CASE WHEN (STEC_NUM_6M = 0 AND STEC_NUM_6ML = 0) THEN NULL ELSE STEC_NUM_6M - STEC_NUM_6ML END, 0) AS STEC_TXN_PROD_6M_MDIFF
      ,ROUND(CASE WHEN STEC_NUM_6ML != 0 THEN (STEC_NUM_6M / STEC_NUM_6ML)-1 ELSE NULL END, 4) AS STEC_TXN_PROD_6M_RDIFF
      ,ROUND(STEC_AMT_6M, 0) AS STEC_TXN_AMT_6M
      ,ROUND(CASE WHEN (STEC_AMT_6M = 0 AND STEC_AMT_6ML = 0) THEN NULL ELSE STEC_AMT_6M - STEC_AMT_6ML END, 0) AS STEC_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN STEC_AMT_6ML != 0 THEN (STEC_AMT_6M / STEC_AMT_6ML)-1 ELSE NULL END, 4) AS STEC_TXN_AMT_6M_RDIFF
      ,ROUND(STEC_NUM_12M, 0) AS STEC_TXN_PROD_12M
      ,ROUND(CASE WHEN (STEC_NUM_12M = 0 AND STEC_NUM_12ML = 0) THEN NULL ELSE STEC_NUM_12M - STEC_NUM_12ML END, 0) AS STEC_TXN_PROD_12M_MDIFF
      ,ROUND(CASE WHEN STEC_NUM_12ML != 0 THEN (STEC_NUM_12M / STEC_NUM_12ML)-1 ELSE NULL END, 4) AS STEC_TXN_PROD_12M_RDIFF
      ,ROUND(STEC_AMT_12M, 0) AS STEC_TXN_AMT_12M
      ,ROUND(CASE WHEN (STEC_AMT_12M = 0 AND STEC_AMT_12ML = 0) THEN NULL ELSE STEC_AMT_12M - STEC_AMT_12ML END, 0) AS STEC_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN STEC_AMT_12ML != 0 THEN (STEC_AMT_12M / STEC_AMT_12ML)-1 ELSE NULL END, 4) AS STEC_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
    SELECT B.PARTY_ID
        -- 3. Foreign Stock 海外股票
        -- MA PROD
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FSMA_NUM_12ML
        -- EC PROD
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FSEC_NUM_12ML
         -- MA AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSMA_AMT_12ML  
         -- EC AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FSEC_AMT_12ML
        
        -- 5. 台股 Stock
        -- MANUAL ORDER
        -- MO NUM
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS STMA_NUM_12ML
         -- MO AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS STMA_AMT_12ML
        -- INTERNET ORDER
        -- IO NUM
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS STEC_NUM_12ML
         -- IO AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE='210' AND B.CHANNEL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS STEC_AMT_12ML
    FROM TRANS_INIT B
    GROUP BY B.PARTY_ID) B
ON A.customer_id = B.PARTY_ID
WHERE A.YYYYMM = :ym;
INSERT INTO DS_SEC.CF_TXN_CURRENCY
SELECT A.CUSTOMER_ID
      ,A.YYYYMM
      -- 台幣計價
      ,ROUND(TWD_BUY_AMT_M, 0) AS TWD_BUY_AMT_M
      ,ROUND(CASE WHEN (TWD_BUY_AMT_M = 0 AND TWD_BUY_AMT_L = 0) THEN NULL ELSE TWD_BUY_AMT_M - TWD_BUY_AMT_L END, 0) AS TWD_BUY_AMT_M_MDIFF
      ,ROUND(CASE WHEN TWD_BUY_AMT_L != 0 THEN (TWD_BUY_AMT_M / TWD_BUY_AMT_L)-1 ELSE NULL END, 4) AS TWD_BUY_AMT_M_RDIFF
      ,ROUND(TWD_SELL_AMT_M, 0) AS TWD_SELL_AMT_M
      ,ROUND(CASE WHEN (TWD_SELL_AMT_M = 0 AND TWD_SELL_AMT_L = 0) THEN NULL ELSE TWD_SELL_AMT_M - TWD_SELL_AMT_L END, 0) AS TWD_SELL_AMT_M_MDIFF
      ,ROUND(CASE WHEN TWD_SELL_AMT_L != 0 THEN (TWD_SELL_AMT_M / TWD_SELL_AMT_L)-1 ELSE NULL END, 4) AS TWD_SELL_AMT_M_RDIFF
      ,ROUND(TWD_TXN_AMT_M, 0) AS TWD_TXN_AMT_M
      ,ROUND(CASE WHEN (TWD_TXN_AMT_M = 0 AND TWD_TXN_AMT_L = 0) THEN NULL ELSE TWD_TXN_AMT_M - TWD_TXN_AMT_L END, 0) AS TWD_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN TWD_TXN_AMT_L != 0 THEN (TWD_TXN_AMT_M / TWD_TXN_AMT_L)-1 ELSE NULL END, 4) AS TWD_TXN_AMT_M_RDIFF
      ,ROUND(TWD_BUY_AMT_3M, 0) AS TWD_BUY_AMT_3M
      ,ROUND(CASE WHEN (TWD_BUY_AMT_3M = 0 AND TWD_BUY_AMT_3ML = 0) THEN NULL ELSE TWD_BUY_AMT_3M - TWD_BUY_AMT_3ML END, 0) AS TWD_BUY_AMT_3M_MDIFF
      ,ROUND(CASE WHEN TWD_BUY_AMT_3ML != 0 THEN (TWD_BUY_AMT_3M / TWD_BUY_AMT_3ML)-1 ELSE NULL END, 4) AS TWD_BUY_AMT_3M_RDIFF
      ,ROUND(TWD_SELL_AMT_3M, 0) AS TWD_SELL_AMT_3M
      ,ROUND(CASE WHEN (TWD_SELL_AMT_3M = 0 AND TWD_SELL_AMT_3ML = 0) THEN NULL ELSE TWD_SELL_AMT_3M - TWD_SELL_AMT_3ML END, 0) AS TWD_SELL_AMT_3M_MDIFF
      ,ROUND(CASE WHEN TWD_SELL_AMT_3ML != 0 THEN (TWD_SELL_AMT_3M / TWD_SELL_AMT_3ML)-1 ELSE NULL END, 4) AS TWD_SELL_AMT_3M_RDIFF
      ,ROUND(TWD_TXN_AMT_3M, 0) AS TWD_TXN_AMT_3M
      ,ROUND(CASE WHEN (TWD_TXN_AMT_3M = 0 AND TWD_TXN_AMT_3ML = 0) THEN NULL ELSE TWD_TXN_AMT_3M - TWD_TXN_AMT_3ML END, 0) AS TWD_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN TWD_TXN_AMT_3ML != 0 THEN (TWD_TXN_AMT_3M / TWD_TXN_AMT_3ML)-1 ELSE NULL END, 4) AS TWD_TXN_AMT_3M_RDIFF 
      ,ROUND(TWD_BUY_AMT_6M, 0) AS TWD_BUY_AMT_6M
      ,ROUND(CASE WHEN (TWD_BUY_AMT_6M = 0 AND TWD_BUY_AMT_6ML = 0) THEN NULL ELSE TWD_BUY_AMT_6M - TWD_BUY_AMT_6ML END, 0) AS TWD_BUY_AMT_6M_MDIFF
      ,ROUND(CASE WHEN TWD_BUY_AMT_6ML != 0 THEN (TWD_BUY_AMT_6M / TWD_BUY_AMT_6ML)-1 ELSE NULL END, 4) AS TWD_BUY_AMT_6M_RDIFF
      ,ROUND(TWD_SELL_AMT_6M, 0) AS TWD_SELL_AMT_6M
      ,ROUND(CASE WHEN (TWD_SELL_AMT_6M = 0 AND TWD_SELL_AMT_6ML = 0) THEN NULL ELSE TWD_SELL_AMT_6M - TWD_SELL_AMT_6ML END, 0) AS TWD_SELL_AMT_6M_MDIFF
      ,ROUND(CASE WHEN TWD_SELL_AMT_6ML != 0 THEN (TWD_SELL_AMT_6M / TWD_SELL_AMT_6ML)-1 ELSE NULL END, 4) AS TWD_SELL_AMT_6M_RDIFF
      ,ROUND(TWD_TXN_AMT_6M, 0) AS TWD_TXN_AMT_6M
      ,ROUND(CASE WHEN (TWD_TXN_AMT_6M = 0 AND TWD_TXN_AMT_6ML = 0) THEN NULL ELSE TWD_TXN_AMT_6M - TWD_TXN_AMT_6ML END, 0) AS TWD_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN TWD_TXN_AMT_6ML != 0 THEN (TWD_TXN_AMT_6M / TWD_TXN_AMT_6ML)-1 ELSE NULL END, 4) AS TWD_TXN_AMT_6M_RDIFF
      ,ROUND(TWD_BUY_AMT_12M, 0) AS TWD_BUY_AMT_12M
      ,ROUND(CASE WHEN (TWD_BUY_AMT_12M = 0 AND TWD_BUY_AMT_12ML = 0) THEN NULL ELSE TWD_BUY_AMT_12M - TWD_BUY_AMT_12ML END, 0) AS TWD_BUY_AMT_12M_MDIFF
      ,ROUND(CASE WHEN TWD_BUY_AMT_12ML != 0 THEN (TWD_BUY_AMT_12M / TWD_BUY_AMT_12ML)-1 ELSE NULL END, 4) AS TWD_BUY_AMT_12M_RDIFF
      ,ROUND(TWD_SELL_AMT_12M, 0) AS TWD_SELL_AMT_12M
      ,ROUND(CASE WHEN (TWD_SELL_AMT_12M = 0 AND TWD_SELL_AMT_12ML = 0) THEN NULL ELSE TWD_SELL_AMT_12M - TWD_SELL_AMT_12ML END, 0) AS TWD_SELL_AMT_12M_MDIFF
      ,ROUND(CASE WHEN TWD_SELL_AMT_12ML != 0 THEN (TWD_SELL_AMT_12M / TWD_SELL_AMT_12ML)-1 ELSE NULL END, 4) AS TWD_SELL_AMT_12M_RDIFF
      ,ROUND(TWD_TXN_AMT_12M, 0) AS TWD_TXN_AMT_12M
      ,ROUND(CASE WHEN (TWD_TXN_AMT_12M = 0 AND TWD_TXN_AMT_12ML = 0) THEN NULL ELSE TWD_TXN_AMT_12M - TWD_TXN_AMT_12ML END, 0) AS TWD_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN TWD_TXN_AMT_12ML != 0 THEN (TWD_TXN_AMT_12M / TWD_TXN_AMT_12ML)-1 ELSE NULL END, 4) AS TWD_TXN_AMT_12M_RDIFF
      
      -- 美金計價
      ,ROUND(USD_BUY_AMT_M, 0) AS USD_BUY_AMT_M
      ,ROUND(CASE WHEN (USD_BUY_AMT_M = 0 AND USD_BUY_AMT_L = 0) THEN NULL ELSE USD_BUY_AMT_M - USD_BUY_AMT_L END, 0) AS USD_BUY_AMT_M_MDIFF
      ,ROUND(CASE WHEN USD_BUY_AMT_L != 0 THEN (USD_BUY_AMT_M / USD_BUY_AMT_L)-1 ELSE NULL END, 4) AS USD_BUY_AMT_M_RDIFF
      ,ROUND(USD_SELL_AMT_M, 0) AS USD_SELL_AMT_M
      ,ROUND(CASE WHEN (USD_SELL_AMT_M = 0 AND USD_SELL_AMT_L = 0) THEN NULL ELSE USD_SELL_AMT_M - USD_SELL_AMT_L END, 0) AS USD_SELL_AMT_M_MDIFF
      ,ROUND(CASE WHEN USD_SELL_AMT_L != 0 THEN (USD_SELL_AMT_M / USD_SELL_AMT_L)-1 ELSE NULL END, 4) AS USD_SELL_AMT_M_RDIFF
      ,ROUND(USD_TXN_AMT_M, 0) AS USD_TXN_AMT_M
      ,ROUND(CASE WHEN (USD_TXN_AMT_M = 0 AND USD_TXN_AMT_L = 0) THEN NULL ELSE USD_TXN_AMT_M - USD_TXN_AMT_L END, 0) AS USD_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN USD_TXN_AMT_L != 0 THEN (USD_TXN_AMT_M / USD_TXN_AMT_L)-1 ELSE NULL END, 4) AS USD_TXN_AMT_M_RDIFF
      ,ROUND(USD_BUY_AMT_3M, 0) AS USD_BUY_AMT_3M
      ,ROUND(CASE WHEN (USD_BUY_AMT_3M = 0 AND USD_BUY_AMT_3ML = 0) THEN NULL ELSE USD_BUY_AMT_3M - USD_BUY_AMT_3ML END, 0) AS USD_BUY_AMT_3M_MDIFF
      ,ROUND(CASE WHEN USD_BUY_AMT_3ML != 0 THEN (USD_BUY_AMT_3M / USD_BUY_AMT_3ML)-1 ELSE NULL END, 4) AS USD_BUY_AMT_3M_RDIFF
      ,ROUND(USD_SELL_AMT_3M, 0) AS USD_SELL_AMT_3M
      ,ROUND(CASE WHEN (USD_SELL_AMT_3M = 0 AND USD_SELL_AMT_3ML = 0) THEN NULL ELSE USD_SELL_AMT_3M - USD_SELL_AMT_3ML END, 0) AS USD_SELL_AMT_3M_MDIFF
      ,ROUND(CASE WHEN USD_SELL_AMT_3ML != 0 THEN (USD_SELL_AMT_3M / USD_SELL_AMT_3ML)-1 ELSE NULL END, 4) AS USD_SELL_AMT_3M_RDIFF
      ,ROUND(USD_TXN_AMT_3M, 0) AS USD_TXN_AMT_3M
      ,ROUND(CASE WHEN (USD_TXN_AMT_3M = 0 AND USD_TXN_AMT_3ML = 0) THEN NULL ELSE USD_TXN_AMT_3M - USD_TXN_AMT_3ML END, 0) AS USD_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN USD_TXN_AMT_3ML != 0 THEN (USD_TXN_AMT_3M / USD_TXN_AMT_3ML)-1 ELSE NULL END, 4) AS USD_TXN_AMT_3M_RDIFF
      ,ROUND(USD_BUY_AMT_6M, 0) AS USD_BUY_AMT_6M
      ,ROUND(CASE WHEN (USD_BUY_AMT_6M = 0 AND USD_BUY_AMT_6ML = 0) THEN NULL ELSE USD_BUY_AMT_6M - USD_BUY_AMT_6ML END, 0) AS USD_BUY_AMT_6M_MDIFF
      ,ROUND(CASE WHEN USD_BUY_AMT_6ML != 0 THEN (USD_BUY_AMT_6M / USD_BUY_AMT_6ML)-1 ELSE NULL END, 4) AS USD_BUY_AMT_6M_RDIFF
      ,ROUND(USD_SELL_AMT_6M, 0) AS USD_SELL_AMT_6M
      ,ROUND(CASE WHEN (USD_SELL_AMT_6M = 0 AND USD_SELL_AMT_6ML = 0) THEN NULL ELSE USD_SELL_AMT_6M - USD_SELL_AMT_6ML END, 0) AS USD_SELL_AMT_6M_MDIFF
      ,ROUND(CASE WHEN USD_SELL_AMT_6ML != 0 THEN (USD_SELL_AMT_6M / USD_SELL_AMT_6ML)-1 ELSE NULL END, 4) AS USD_SELL_AMT_6M_RDIFF
      ,ROUND(USD_TXN_AMT_6M, 0) AS USD_TXN_AMT_6M
      ,ROUND(CASE WHEN (USD_TXN_AMT_6M = 0 AND USD_TXN_AMT_6ML = 0) THEN NULL ELSE USD_TXN_AMT_6M - USD_TXN_AMT_6ML END, 0) AS USD_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN USD_TXN_AMT_6ML != 0 THEN (USD_TXN_AMT_6M / USD_TXN_AMT_6ML)-1 ELSE NULL END, 4) AS USD_TXN_AMT_6M_RDIFF
      ,ROUND(USD_BUY_AMT_12M, 0) AS USD_BUY_AMT_12M
      ,ROUND(CASE WHEN (USD_BUY_AMT_12M = 0 AND USD_BUY_AMT_12ML = 0) THEN NULL ELSE USD_BUY_AMT_12M - USD_BUY_AMT_12ML END, 0) AS USD_BUY_AMT_12M_MDIFF
      ,ROUND(CASE WHEN USD_BUY_AMT_12ML != 0 THEN (USD_BUY_AMT_12M / USD_BUY_AMT_12ML)-1 ELSE NULL END, 4) AS USD_BUY_AMT_12M_RDIFF
      ,ROUND(USD_SELL_AMT_12M, 0) AS USD_SELL_AMT_12M
      ,ROUND(CASE WHEN (USD_SELL_AMT_12M = 0 AND USD_SELL_AMT_12ML = 0) THEN NULL ELSE USD_SELL_AMT_12M - USD_SELL_AMT_12ML END, 0) AS USD_SELL_AMT_12M_MDIFF
      ,ROUND(CASE WHEN USD_SELL_AMT_12ML != 0 THEN (USD_SELL_AMT_12M / USD_SELL_AMT_12ML)-1 ELSE NULL END, 4) AS USD_SELL_AMT_12M_RDIFF
      ,ROUND(USD_TXN_AMT_12M, 0) AS USD_TXN_AMT_12M
      ,ROUND(CASE WHEN (USD_TXN_AMT_12M = 0 AND USD_TXN_AMT_12ML = 0) THEN NULL ELSE USD_TXN_AMT_12M - USD_TXN_AMT_12ML END, 0) AS USD_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN USD_TXN_AMT_12ML != 0 THEN (USD_TXN_AMT_12M / USD_TXN_AMT_12ML)-1 ELSE NULL END, 4) AS USD_TXN_AMT_12M_RDIFF
      
      -- 其他幣別計價
      ,ROUND(OD_BUY_AMT_M, 0) AS OD_BUY_AMT_M
      ,ROUND(CASE WHEN (OD_BUY_AMT_M = 0 AND OD_BUY_AMT_L = 0) THEN NULL ELSE OD_BUY_AMT_M - OD_BUY_AMT_L END, 0) AS OD_BUY_AMT_M_MDIFF
      ,ROUND(CASE WHEN OD_BUY_AMT_L != 0 THEN (OD_BUY_AMT_M / OD_BUY_AMT_L)-1 ELSE NULL END, 4) AS OD_BUY_AMT_M_RDIFF
      ,ROUND(OD_SELL_AMT_M, 0) AS OD_SELL_AMT_M
      ,ROUND(CASE WHEN (OD_SELL_AMT_M = 0 AND OD_SELL_AMT_L = 0) THEN NULL ELSE OD_SELL_AMT_M - OD_SELL_AMT_L END, 0) AS OD_SELL_AMT_M_MDIFF
      ,ROUND(CASE WHEN OD_SELL_AMT_L != 0 THEN (OD_SELL_AMT_M / OD_SELL_AMT_L)-1 ELSE NULL END, 4) AS OD_SELL_AMT_M_RDIFF
      ,ROUND(OD_TXN_AMT_M, 0) AS OD_TXN_AMT_M
      ,ROUND(CASE WHEN (OD_TXN_AMT_M = 0 AND OD_TXN_AMT_L = 0) THEN NULL ELSE OD_TXN_AMT_M - OD_TXN_AMT_L END, 0) AS OD_TXN_AMT_M_MDIFF
      ,ROUND(CASE WHEN OD_TXN_AMT_L != 0 THEN (OD_TXN_AMT_M / OD_TXN_AMT_L)-1 ELSE NULL END, 4) AS OD_TXN_AMT_M_RDIFF
      ,ROUND(OD_BUY_AMT_3M, 0) AS OD_BUY_AMT_3M
      ,ROUND(CASE WHEN (OD_BUY_AMT_3M = 0 AND OD_BUY_AMT_3ML = 0) THEN NULL ELSE OD_BUY_AMT_3M - OD_BUY_AMT_3ML END, 0) AS OD_BUY_AMT_3M_MDIFF
      ,ROUND(CASE WHEN OD_BUY_AMT_3ML != 0 THEN (OD_BUY_AMT_3M / OD_BUY_AMT_3ML)-1 ELSE NULL END, 4) AS OD_BUY_AMT_3M_RDIFF
      ,ROUND(OD_SELL_AMT_3M, 0) AS OD_SELL_AMT_3M
      ,ROUND(CASE WHEN (OD_SELL_AMT_3M = 0 AND OD_SELL_AMT_3ML = 0) THEN NULL ELSE OD_SELL_AMT_3M - OD_SELL_AMT_3ML END, 0) AS OD_SELL_AMT_3M_MDIFF
      ,ROUND(CASE WHEN OD_SELL_AMT_3ML != 0 THEN (OD_SELL_AMT_3M / OD_SELL_AMT_3ML)-1 ELSE NULL END, 4) AS OD_SELL_AMT_3M_RDIFF
      ,ROUND(OD_TXN_AMT_3M, 0) AS OD_TXN_AMT_3M
      ,ROUND(CASE WHEN (OD_TXN_AMT_3M = 0 AND OD_TXN_AMT_3ML = 0) THEN NULL ELSE OD_TXN_AMT_3M - OD_TXN_AMT_3ML END, 0) AS OD_TXN_AMT_3M_MDIFF
      ,ROUND(CASE WHEN OD_TXN_AMT_3ML != 0 THEN (OD_TXN_AMT_3M / OD_TXN_AMT_3ML)-1 ELSE NULL END, 4) AS OD_TXN_AMT_3M_RDIFF 
      ,ROUND(OD_BUY_AMT_6M, 0) AS OD_BUY_AMT_6M
      ,ROUND(CASE WHEN (OD_BUY_AMT_6M = 0 AND OD_BUY_AMT_6ML = 0) THEN NULL ELSE OD_BUY_AMT_6M - OD_BUY_AMT_6ML END, 0) AS OD_BUY_AMT_6M_MDIFF
      ,ROUND(CASE WHEN OD_BUY_AMT_6ML != 0 THEN (OD_BUY_AMT_6M / OD_BUY_AMT_6ML)-1 ELSE NULL END, 4) AS OD_BUY_AMT_6M_RDIFF
      ,ROUND(OD_SELL_AMT_6M, 0) AS OD_SELL_AMT_6M
      ,ROUND(CASE WHEN (OD_SELL_AMT_6M = 0 AND OD_SELL_AMT_6ML = 0) THEN NULL ELSE OD_SELL_AMT_6M - OD_SELL_AMT_6ML END, 0) AS OD_SELL_AMT_6M_MDIFF
      ,ROUND(CASE WHEN OD_SELL_AMT_6ML != 0 THEN (OD_SELL_AMT_6M / OD_SELL_AMT_6ML)-1 ELSE NULL END, 4) AS OD_SELL_AMT_6M_RDIFF
      ,ROUND(OD_TXN_AMT_6M, 0) AS OD_TXN_AMT_6M
      ,ROUND(CASE WHEN (OD_TXN_AMT_6M = 0 AND OD_TXN_AMT_6ML = 0) THEN NULL ELSE OD_TXN_AMT_6M - OD_TXN_AMT_6ML END, 0) AS OD_TXN_AMT_6M_MDIFF
      ,ROUND(CASE WHEN OD_TXN_AMT_6ML != 0 THEN (OD_TXN_AMT_6M / OD_TXN_AMT_6ML)-1 ELSE NULL END, 4) AS OD_TXN_AMT_6M_RDIFF
      ,ROUND(OD_BUY_AMT_12M, 0) AS OD_BUY_AMT_12M
      ,ROUND(CASE WHEN (OD_BUY_AMT_12M = 0 AND OD_BUY_AMT_12ML = 0) THEN NULL ELSE OD_BUY_AMT_12M - OD_BUY_AMT_12ML END, 0) AS OD_BUY_AMT_12M_MDIFF
      ,ROUND(CASE WHEN OD_BUY_AMT_12ML != 0 THEN (OD_BUY_AMT_12M / OD_BUY_AMT_12ML)-1 ELSE NULL END, 4) AS OD_BUY_AMT_12M_RDIFF
      ,ROUND(OD_SELL_AMT_12M, 0) AS OD_SELL_AMT_12M
      ,ROUND(CASE WHEN (OD_SELL_AMT_12M = 0 AND OD_SELL_AMT_12ML = 0) THEN NULL ELSE OD_SELL_AMT_12M - OD_SELL_AMT_12ML END, 0) AS OD_SELL_AMT_12M_MDIFF
      ,ROUND(CASE WHEN OD_SELL_AMT_12ML != 0 THEN (OD_SELL_AMT_12M / OD_SELL_AMT_12ML)-1 ELSE NULL END, 4) AS OD_SELL_AMT_12M_RDIFF
      ,ROUND(OD_TXN_AMT_12M, 0) AS OD_TXN_AMT_12M
      ,ROUND(CASE WHEN (OD_TXN_AMT_12M = 0 AND OD_TXN_AMT_12ML = 0) THEN NULL ELSE OD_TXN_AMT_12M - OD_TXN_AMT_12ML END, 0) AS OD_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN OD_TXN_AMT_12ML != 0 THEN (OD_TXN_AMT_12M / OD_TXN_AMT_12ML)-1 ELSE NULL END, 4) AS OD_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
        SELECT B.PARTY_ID
        -- 1. NT Dollar 台幣計價
        -- BUY AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_BUY_AMT_12ML
        -- SELL AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='TWD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_SELL_AMT_12ML
        -- TRANS AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='TWD' THEN B.TXN_AMT_TWD ELSE 0 END) AS TWD_TXN_AMT_12ML
        
        -- 3. USD 美金計價
        -- BUY AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_BUY_AMT_12ML
        -- SELL AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='USD' AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_SELL_AMT_12ML
        -- TRANS AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE='USD' THEN B.TXN_AMT_TWD ELSE 0 END) AS USD_TXN_AMT_12ML
        
        -- 2. Other dollars 其他幣別計價
        -- BUY AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_BUY_AMT_12ML
        -- SELL AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_SELL_AMT_12ML
        -- TRANS AMOUNT
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN B.TXN_AMT_TWD ELSE 0 END) AS OD_TXN_AMT_12ML
    FROM TRANS_INIT B
    GROUP BY B.PARTY_ID) B
ON A.customer_id = B.PARTY_ID
WHERE A.YYYYMM = :ym;
