      ,ROUND(CASE WHEN (BR_BUY_PROD_12M = 0 AND BR_BUY_PROD_12ML = 0) THEN NULL ELSE BR_BUY_PROD_12M - BR_BUY_PROD_12ML END,0) AS BR_BUY_PROD_12M_MDIFF
      ,ROUND(CASE WHEN BR_BUY_PROD_12ML != 0 THEN (BR_BUY_PROD_12M / BR_BUY_PROD_12ML)-1 ELSE NULL END, 4) AS BR_BUY_PROD_12M_RDIFF
      ,ROUND(BR_BUY_AMT_12M,0)BR_BUY_AMT_12M
      ,ROUND(CASE WHEN (BR_BUY_AMT_12M = 0 AND BR_BUY_AMT_12ML = 0) THEN NULL ELSE BR_BUY_AMT_12M - BR_BUY_AMT_12ML END,0) AS BR_BUY_AMT_12M_MDIFF
      ,ROUND(CASE WHEN BR_BUY_AMT_12ML != 0 THEN (BR_BUY_AMT_12M / BR_BUY_AMT_12ML)-1 ELSE NULL END, 4) AS BR_BUY_AMT_12M_RDIFF
      ,ROUND(BR_SEL_PROD_12M,0)BR_SEL_PROD_12M
      ,ROUND(CASE WHEN (BR_SEL_PROD_12M = 0 AND BR_SEL_PROD_12ML = 0) THEN NULL ELSE BR_SEL_PROD_12M - BR_SEL_PROD_12ML END,0) AS BR_SEL_PROD_12M_MDIFF
      ,ROUND(CASE WHEN BR_SEL_PROD_12ML != 0 THEN (BR_SEL_PROD_12M / BR_SEL_PROD_12ML)-1 ELSE NULL END, 4) AS BR_SEL_PROD_12M_RDIFF
      ,ROUND(BR_SELL_AMT_12M,0)BR_SELL_AMT_12M
      ,ROUND(CASE WHEN (BR_SELL_AMT_12M = 0 AND BR_SELL_AMT_12ML = 0) THEN NULL ELSE BR_SELL_AMT_12M - BR_SELL_AMT_12ML END,0) AS BR_SELL_AMT_12M_MDIFF
      ,ROUND(CASE WHEN BR_SELL_AMT_12ML != 0 THEN (BR_SELL_AMT_12M / BR_SELL_AMT_12ML)-1 ELSE NULL END, 4) AS BR_SELL_AMT_12M_RDIFF
      ,ROUND(BR_TXN_PROD_12M,0)BR_TXN_PROD_12M
      ,ROUND(CASE WHEN (BR_TXN_PROD_12M = 0 AND BR_TXN_PROD_12ML = 0) THEN NULL ELSE BR_TXN_PROD_12M - BR_TXN_PROD_12ML END,0) AS BR_TXN_PROD_12M_MDIFF
      ,ROUND(CASE WHEN BR_TXN_PROD_12ML != 0 THEN (BR_TXN_PROD_12M / BR_TXN_PROD_12ML)-1 ELSE NULL END, 4) AS BR_TXN_PROD_12M_RDIFF
      ,ROUND(BR_TXN_AMT_12M,0)BR_TXN_AMT_12M
      ,ROUND(CASE WHEN (BR_TXN_AMT_12M = 0 AND BR_TXN_AMT_12ML = 0) THEN NULL ELSE BR_TXN_AMT_12M - BR_TXN_AMT_12ML END,0) AS BR_TXN_AMT_12M_MDIFF
      ,ROUND(CASE WHEN BR_TXN_AMT_12ML != 0 THEN (BR_TXN_AMT_12M / BR_TXN_AMT_12ML)-1 ELSE NULL END, 4) AS BR_TXN_AMT_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN (
        SELECT B.PARTY_ID
       -- 4. Financial Product 財管商品
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS FP_BUY_PROD_12ML
        
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TRANS_NUM ELSE 0 END) AS FP_SEL_PROD_12ML
        
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TRANS_NUM ELSE 0 END) AS FP_TXN_PROD_12ML
        
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='001' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_BUY_AMT_12ML
        
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') AND B.BUY_SELL_CODE='002' THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_SELL_AMT_12ML
        
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_3ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_6M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_6ML
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_12M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN B.TXN_AMT_TWD ELSE 0 END) AS FP_TXN_AMT_12ML
        
        -- 5. BROKERED COMMODITY 經紀商品
        ,SUM(CASE WHEN B.TXN_YYYYMM = :ym AND B.PROD_MTYPE_CODE IN ('110', '150', '160', '210', '3C0','3F0','3P0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS BR_BUY_PROD_M
        ,SUM(CASE WHEN B.TXN_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('110', '150', '160', '210', '3C0','3F0','3P0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS BR_BUY_PROD_L
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND B.PROD_MTYPE_CODE IN ('110', '150', '160', '210', '3C0','3F0','3P0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS BR_BUY_PROD_3M
        ,SUM(CASE WHEN B.TXN_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND B.PROD_MTYPE_CODE IN ('110', '150', '160', '210', '3C0','3F0','3P0') AND B.BUY_SELL_CODE='001' THEN B.TRANS_NUM ELSE 0 END) AS BR_BUY_PROD_3ML
